contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 oracleAdvance) public {
        // Ensure the oracle has a chance to be ahead of version 0.
        // We bound oracleAdvance to at least 1 to guarantee the oracle's current version differs from 0.
        bound(oracleAdvance, 1, 255);
        // Deploy a minimal oracle that returns version = oracleAdvance on currentVersion()
        address oracleAddr = address(new MockOracle(oracleAdvance));
        // Initialize the product with the mock oracle.
        // We need to call initialize through the controller pattern, but since C expects msg.sender to be the controller,
