        // Deploy a simple controller stub.
        vm.prank(address(this));
        // We cannot call initialize directly because it checks msg.sender via UControllerProvider.
        // Instead we deploy a controller stub that calls initialize on c.
        ControllerStub stub = new ControllerStub(c, IOracleProvider(oracleAddr));
        // The initialize was called in stub's constructor, product is now ready.

        // Now read currentVersion from the product.
        // The property: the version returned by currentVersion() must be equal to the oracle's current version.
        uint256 productVersion = c.currentVersion().version;
        uint256 oracleVersion = IOracleProvider(oracleAddr).currentVersion().version;
        assertEq(productVersion, oracleVersion);
    }
