contract MockOracle {
    uint8 public _advance;
    constructor(uint8 advance_) {
        _advance = advance_;
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        // Return a version equal to _advance, price is arbitrary
        return IOracleProvider.OracleVersion({
            version: uint256(_advance),
            timestamp: uint256(_advance),
            price: Fixed18.wrap(int256(_advance) * 1e18)
        });
    }
    function atVersion(uint256 oracleVersion) external view returns (IOracleProvider.OracleVersion memory) {
        // Return the same data as currentVersion if matched, else dummy
        return IOracleProvider.OracleVersion({
            version: oracleVersion,
            timestamp: oracleVersion,
            price: Fixed18.wrap(0)
        });
    }
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return currentVersion();
    }
}

