        // We must also satisfy payoffDefinition valid constraint.
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TST";
        info.oracle = oracle;
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASS,
