import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool transform) public {
        // The bug is that _transform is not called, so the price returned is the raw oracle price.
        // The reference always applies the payoff transform to the price.
        // If the payoff definition would transform the price, the two outputs differ.
        // We use a fuzzed bool to decide whether the payoff definition should be a passthrough (identity)
        // or something that modifies the price. If it modifies, reference and bug diverge.
        // However, we cannot set the payoff definition via public surface without knowing internal setup.
        // Instead, we observe that the reference contract's currentVersion() price equals its atVersion(latestVersion()).price,
        // which also undergoes _transform. Both reference and bug share the same oracle, so both see the same raw price.
        // We need a property that reference satisfies but bug violates.
        // The bug omits _transform, so currentVersion() returns oracle().currentVersion() directly.
        // The reference's currentVersion() is oracle().currentVersion() with price transformed.
        // We cannot directly observe the raw oracle price from C's public surface unless we call oracle().currentVersion()
        // and compare to c.currentVersion().price. oracle() is public, so we can call it.
        IOracleProvider oracle = c.oracle();
        try oracle.currentVersion() returns (IOracleProvider.OracleVersion memory rawVersion) {
            try c.currentVersion() returns (IOracleProvider.OracleVersion memory transformedVersion) {
                // The reference's transformed price must equal payoffDefinition().transform(rawVersion.price).
                // The bug returns rawVersion.price, so if payoffDefinition is not identity, they differ.
                // We compute the expected transformed price manually using the public payoffDefinition().transform.
                PayoffDefinition memory def = c.payoffDefinition();
                Fixed18 expectedPrice = def.transform(rawVersion.price);
                // Property: the returned price must match the payoff-transformed price.
                assertEq(Fixed18.unwrap(transformedVersion.price), Fixed18.unwrap(expectedPrice));
            } catch {
                fail("currentVersion() reverted");
            }
        } catch {
            fail("oracle().currentVersion() reverted");
        }
    }
}

