pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rawPrice) public {
        // Bound rawPrice to avoid overflow in price transformation, but keep range wide enough
        // to include values where the transformation differs from identity.
        rawPrice = bound(rawPrice, 1e18, 1e36); // wide positive range for Fixed18 price

        // Setup oracle with known raw price using a mock that returns rawPrice
        // Deploy a minimal oracle mock inline
        MockOracle oracle = new MockOracle(rawPrice);

        // Use a payoff definition that transforms the price (e.g., NEGATIVE direction to invert)
        // PayoffDefinition struct: payoffType, payoffDirection, data
        // We'll use a simple PASSTHROUGH with NEGATIVE direction to invert price.
        // PayoffType: 0 (PASSTHROUGH), PayoffDirection: 1 (NEGATIVE), data: bytes30(0)
        bytes memory payoffBytes = abi.encode(uint8(0), uint8(1), bytes30(0));
        PayoffDefinition memory payoffDef = abi.decode(payoffBytes, (PayoffDefinition));

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: payoffDef,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0.01e18),
            takerFee: UFixed18.wrap(0.01e18),
            positionFee: UFixed18.wrap(0.01e18),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(int128(1e18)),
                targetRate: PackedFixed18.wrap(int128(0.1e18)),
                targetUtilization: PackedUFixed18.wrap(uint128(0.8e18))
            })
        });

        // Initialize the product; msg.sender must be controller, so we mock that as well
        // But c.initialize expects msg.sender to be controller, and it calls __UControllerProvider__initialize which requires isContract
        // We'll deploy a minimal controller mock
        MockController controller = new MockController();
        vm.prank(address(controller));
        c.initialize(info);

        // Now retrieve currentVersion from c
        IOracleProvider.OracleVersion memory result = c.currentVersion();

        // The reference transforms the raw oracle price according to payoffDefinition.
        // For PASSTHROUGH + NEGATIVE direction, the transformation should invert the price: -rawPrice
        // The buggy version returns the raw price unchanged.
        // We assert that result.price.unwrap() == -int256(rawPrice) (the reference behavior).
        // If buggy, result.price.unwrap() == int256(rawPrice), which will fail for nonzero rawPrice.
        assertEq(result.price.unwrap(), -int256(rawPrice));
    }
}

